mapper.select:
select d.*, l.lab_name as labName, l.department_id as departmentId
from lab_device d
join lab l on l.id = d.lab_id
where d.deleted = 0
  and l.deleted = 0

    and d.lab_id = #{labId}


    and (

        d.device_name like concat('%', #{deviceName}, '%')


        or


        d.device_code like concat('%', #{deviceCode}, '%')

    )


    and d.status = #{status}


    and l.department_id = #{departmentId}

order by d.id desc
limit #{offset}, #{pageSize}

select count(*)
from lab_device d
join lab l on l.id = d.lab_id
where d.deleted = 0
  and l.deleted = 0

    and d.lab_id = #{labId}


    and (

        d.device_name like concat('%', #{deviceName}, '%')


        or


        d.device_code like concat('%', #{deviceCode}, '%')

    )


    and d.status = #{status}


    and l.department_id = #{departmentId}

select d.*, l.lab_name as labName, l.department_id as departmentId from lab_device d join lab l on l.id = d.lab_id where d.deleted = 0 and l.deleted = 0
and d.lab_id = #{labId}
and l.department_id = #{departmentId}
order by d.id asc

select d.*, l.lab_name as labName, l.department_id as departmentId from lab_device d join lab l on l.id = d.lab_id where d.deleted = 0 and l.deleted = 0 and d.status != 1
and l.department_id = #{departmentId}
order by d.id desc

mapper.update:
update lab_device
set status = #{status}
where id = #{id}
    and deleted = 0
